import{a as r}from"./chunk-MTFXE4MC.js";import{m as i}from"./chunk-7TORLCSQ.js";var o={"karting-cartel":{intro:"Wheel to wheel, lap after lap. The fastest way to find out what you are made of.",body:["The Karting Cartel is where the noise starts. Purpose-built karts, a circuit that rewards a clean line over brute throttle, and timing that does not care how good you think you are.","Race solo against the clock or bring a group and settle it properly. Marshals brief every session, so first-timers and regulars share the same grid safely."],highlights:["Timed sessions with live lap boards","Race-prepared karts and full safety gear provided","Group and corporate race formats","Marshal briefing before every session"],gallery:[{src:"/arena-ng-preview/images/arenas/karting-cartel.jpg",alt:"The Karting Cartel arena wall, with a kart mid-corner"},{src:"/arena-ng-preview/images/murals/karting-cartel-wall.jpg",alt:"The Karting Cartel perimeter wall artwork"}]},"battle-x-arena":{intro:"Two teams. One objective. No pain, no game.",body:["Battle X Arena is close-quarters team combat built around cover, timing and communication. Containers, barricades and sightlines that punish anyone who moves without a plan.","Squads run as Red Force and Black Ops, and the scoreboard settles the argument. Full protective equipment is issued and fitted before every round."],highlights:["Team-based objective rounds","Full protective equipment issued and fitted","Purpose-built cover and container layout","Squad formats for groups and events"],gallery:[{src:"/arena-ng-preview/images/arenas/battle-x-arena.jpg",alt:"The Battle X Arena interior, lit in orange and yellow"},{src:"/arena-ng-preview/images/murals/battle-x-target-gate.jpg",alt:"The Battle X and Target Arena entrance gate"},{src:"/arena-ng-preview/images/murals/battle-x-no-pain-no-game.jpg",alt:'The Battle X Arena "No pain, no game" wall'},{src:"/arena-ng-preview/images/murals/red-force-team-1.jpg",alt:"The Red Force team wall \u2014 one team, one mission"},{src:"/arena-ng-preview/images/murals/black-ops-team-2.jpg",alt:"The Black Ops team wall \u2014 no mercy, no retreat"}]},"skyrush-zipline":{intro:"Adventure above ground. Step off the platform and let the line do the rest.",body:["SkyRush runs from the tower across the site, and the only difficult part is the first step. Harnesses are fitted and checked by staff, and the line is inspected before every operating day.","It is the shortest ride at the arena and the one people talk about longest."],highlights:["Harness fitted and checked by trained staff","Daily line and equipment inspection","Tower launch platform","Suitable for first-timers"],gallery:[{src:"/arena-ng-preview/images/arenas/skyrush-zipline.jpg",alt:"The SkyRush Zipline tower wall artwork"}]},"powerplay-turf":{intro:"Hit hard. Play smart. The turf is waiting.",body:["PowerPlay Turf is the arena for cricket and five-a-side under lights. Book an hour with friends or run a full league fixture on a surface built for it.","Floodlit for evening play, so the game does not stop when the sun does."],highlights:["Floodlit for evening and night play","Cricket and five-a-side formats","Hourly bookings and league fixtures","Equipment available on site"],gallery:[{src:"/arena-ng-preview/images/arena-logos/powerplay-turf.jpg",alt:"The PowerPlay Turf brand artwork"},{src:"/arena-ng-preview/images/murals/adventure-starts-here.jpg",alt:'The venue mural, including its "Play like a pro" cricket panel'},{src:"/arena-ng-preview/images/hero/hero-entrance-wall.jpg",alt:"The entrance wall, showing the cricket pictogram among the activities"}]},"pickle-pit-arena":{intro:"Where every shot matters.",body:["Pickleball is the easiest racquet sport to start and the hardest to put down. The Pickle Pit has dedicated courts, paddles and balls ready to go.","Turn up in a pair or a four. Rallies start within a minute of picking up a paddle."],highlights:["Dedicated pickleball courts","Paddles and balls provided","Singles and doubles play","Beginner friendly"],gallery:[{src:"/arena-ng-preview/images/arena-logos/pickle-pit-arena.jpg",alt:"The Pickle Pit Arena brand artwork"},{src:"/arena-ng-preview/images/hero/hero-entrance-wall.jpg",alt:"The entrance wall, showing the pickleball pictogram among the activities"}]},"airgun-shooting":{intro:"Calm mind. Steady hand. Precise shot.",body:["The airgun range is about control rather than speed. Breathing, trigger discipline and the patience to take the same shot again until the group tightens.","Every session is supervised, and the range runs to a strict safety brief that nobody skips."],highlights:["Supervised range with mandatory safety brief","Scoped airguns and eye protection provided","Paper targets scored per session","Coaching available for beginners"],gallery:[{src:"/arena-ng-preview/images/arenas/airgun-shooting.jpg",alt:"The Airgun Shooting range wall artwork"},{src:"/arena-ng-preview/images/murals/airgun-focus-aim-control.jpg",alt:'The airgun range "Focus. Aim. Control. Achieve." wall'},{src:"/arena-ng-preview/images/murals/airgun-focus-breathe-squeeze.jpg",alt:'The airgun range "Focus. Breathe. Squeeze. Repeat." wall'}]},"quick-jump":{intro:"Take the leap!",body:["Quick Jump is the drop from the tower, harnessed and controlled, with nothing between the decision and the landing but a couple of very loud seconds.","Staff fit and double-check every harness before the platform gate opens."],highlights:["Harness fitted and double-checked before every jump","Tower platform with controlled descent","Suitable for children and adults","Staff supervised at platform and landing"],gallery:[{src:"/arena-ng-preview/images/murals/quick-jump-tower.jpg",alt:"The Quick Jump tower and its artwork"}]},"paint-ball":{intro:"Get painted. Live the game.",body:["Paintball at Xtreme Arena is played across marked ground with cover, objectives and enough colour to make the scoreboard obvious.","Masks and overalls are issued to everyone, and the safety brief covers the rules that keep the game fun rather than painful."],highlights:["Masks, overalls and markers provided","Objective-based rounds across marked ground","Safety brief before every game","Paintball packs available per player"],gallery:[{src:"/arena-ng-preview/images/arenas/paint-ball.jpg",alt:"The Paint Ball entrance artwork"},{src:"/arena-ng-preview/images/murals/paintball-get-painted.jpg",alt:'The "Get painted, live the game" paintball wall'}]},"target-area":{intro:"Lock. Aim. Fire.",body:["The Target Area is the combat zone proving ground \u2014 crosshairs, reload points and a wall of colour that keeps score for you.","Run it as practice before a Battle X round, or as its own session."],highlights:["Marked combat zone with reload points","Runs standalone or alongside Battle X","Protective equipment provided","Supervised throughout"],gallery:[{src:"/arena-ng-preview/images/arenas/target-area.jpg",alt:"The Target Area combat zone mural"}]},"archery-zone":{intro:"Aim. Focus. Release. Consistency today, victory tomorrow.",body:["Archery rewards the people who slow down. Stance, draw, anchor, release \u2014 and then doing it identically again.","Bows are matched to each archer and coaching is on hand for anyone shooting for the first time."],highlights:["Bows matched to each archer","Coaching for first-time archers","Scored target sessions","Supervised shooting line"],gallery:[{src:"/arena-ng-preview/images/arenas/archery-zone.jpg",alt:"The Archery Zone entrance artwork"},{src:"/arena-ng-preview/images/murals/archery-focus-aim-conquer.jpg",alt:'The archery "Focus. Aim. Conquer." wall'},{src:"/arena-ng-preview/images/murals/archery-aim-focus-hit-repeat.jpg",alt:'The archery "Aim. Focus. Hit. Repeat." wall'}]},"pitstop-cafe":{intro:"Refuel your speed.",body:["Pitstop Caf\xE9 is where the day slows down for twenty minutes. Coffee, cold drinks and food between sessions, with somewhere to sit and argue about lap times.","Open throughout the day for players and for anyone waiting on them."],highlights:["Coffee, cold drinks and food","Seating for groups between sessions","Open to visitors as well as players"],gallery:[{src:"/arena-ng-preview/images/arena-logos/pitstop-cafe.jpg",alt:"The Pitstop Cafe brand artwork"},{src:"/arena-ng-preview/images/arena-logos/pitstop-island.jpg",alt:"The Pitstop Island brand artwork"},{src:"/arena-ng-preview/images/hero/hero-entrance-wall.jpg",alt:"The entrance wall, showing the cafe pictogram among the activities"}]},"pitbull-motoride":{intro:"Fuel your adrenaline.",body:["Pitbull Motoride puts you on two wheels on a track built for it. Controlled, supervised and considerably faster than it looks from the fence.","Full protective gear is issued and every rider is briefed before setting off."],highlights:["Full protective gear issued","Rider briefing before every session","Purpose-built track","Supervised riding"],gallery:[{src:"/arena-ng-preview/images/arena-logos/pitbull-motoride.jpg",alt:"The Pitbull Motoride brand artwork"}]}};var s=class t{all=r;findBySlug(e){return r.find(a=>a.slug===e)}detailFor(e){return o[e]}others(e,a=4){return r.filter(n=>n.slug!==e).slice(0,a)}static \u0275fac=function(a){return new(a||t)};static \u0275prov=i({token:t,factory:t.\u0275fac,providedIn:"root"})};export{s as a};
